/** Scatter: 2025 share vs YoY ??? who is concentrated and still growing */
export type ShareGrowthPoint = {
  market: string;
  short: string;
  sharePct: number;
  yoyPct: number;
  units: number;
  region: string;
  fill: string;
};

export const SHARE_GROWTH_SCATTER: ShareGrowthPoint[] = MARKET_SHARES.map((m) => ({
  market: m.market,
  short: m.short,
  sharePct: m.share2025Pct,
  yoyPct: m.yoyPct,
  units: m.units2025,
  region: m.region,
  fill: m.fill,
}));

/** Share delta bridge: who gained / lost pp of world installs */
export const SHARE_DELTA_BRIDGE = MARKET_SHARES.slice(0, 8).map((m) => ({
  market: m.short,
  share2024Pct: m.share2024Pct,
  share2025Pct: m.share2025Pct,
  deltaPp: Number((m.share2025Pct - m.share2024Pct).toFixed(1)),
  fill: m.fill,
  confidence: m.confidence,
}));

export const SOURCES = [
  { label: "IFR US double-digit growth (Jun 2026)", url: IFR_US_URL },
  { label: "IFR Executive Roundtable (24 Jun 2026)", url: IFR_ROUNDTABLE_URL },
  { label: "IFR World Robotics 2025 release", url: IFR_WR_URL },
  { label: "IFR China press release (25 Sep 2025)", url: IFR_CHINA_URL },
  { label: "Prior concentration post (2024 ladder)", url: PRIOR_CONC_PATH },
  { label: "Q3 2026 YoY update", url: Q3_UPDATE_PATH },
] as const;

export function fmtUnits(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(2)}M`;
  if (n >= 1_000) return `${Math.round(n / 1_000)}k`;
  return String(n);
}

export function fmtPct(n: number, digits = 0): string {
  return `${n.toFixed(digits)}%`;
}

export function fmtPp(n: number, digits = 1): string {
  const sign = n > 0 ? "+" : "";
  return `${sign}${n.toFixed(digits)} pp`;
}

