"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CHINA_SUPPLIER_SERIES,
  CONCENTRATION_CURVE,
  HEADLINE,
  INDUSTRY_SHARES,
  MARKET_SHARES,
  REGION_SHARES,
  SHARE_DELTA_BRIDGE,
  SHARE_GROWTH_SCATTER,
  SOURCE_NOTE,
  TOP_K_LADDER,
  TOP_K_PATH,
  fmtPct,
  fmtPp,
  fmtUnits,
} from "@/data/industrial-robotics-concentration-2026q3-data";

// viz-types: Lorenz area+line, ranked share bars, path multi-line, share-delta bars, region donut, supplier stacked area, industry bars, share??growth scatter | layout: default

type ViewId = "ladder" | "path" | "regions" | "industry";
type LadderMetric = "share2025Pct" | "units2025" | "cumulative2025Pct";
type PathSeries = "top1" | "top3" | "top5" | "asia" | "hhi";

const ROSE = "#f43f5e";
const AMBER = "#f59e0b";
const SKY = "#0ea5e9";
const VIOLET = "#8b5cf6";
const TEAL = "#14b8a6";
const SLATE = "#64748b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function IndustrialRoboticsConcentration2026q3Dashboard() {
  const [view, setView] = useState<ViewId>("ladder");
  const [ladderMetric, setLadderMetric] = useState<LadderMetric>("share2025Pct");
  const [showEqualLine, setShowEqualLine] = useState(true);
  const [pathSeries, setPathSeries] = useState<PathSeries>("top1");
  const [industryLens, setIndustryLens] = useState<"share" | "yoy">("share");
  const [regionVintage, setRegionVintage] = useState<"2024" | "2025">("2025");

  const ladderBars = useMemo(() => {
    return [...MARKET_SHARES]
      .map((m) => ({
        ...m,
        value:
          ladderMetric === "share2025Pct"
            ? m.share2025Pct
            : ladderMetric === "units2025"
              ? m.units2025
              : m.cumulative2025Pct,
      }))
      .sort((a, b) => b.value - a.value);
  }, [ladderMetric]);

  const regionDonut = useMemo(
    () =>
      REGION_SHARES.map((r) => ({
        name: r.short,
        value: regionVintage === "2025" ? r.share2025Pct : r.share2024Pct,
        fill: r.fill,
      })),
    [regionVintage],
  );

  const industryBars = useMemo(() => {
    return INDUSTRY_SHARES.map((i) => ({
      ...i,
      value: industryLens === "share" ? i.share2024Pct : i.yoy2025Pct,
      label:
        industryLens === "share"
          ? `${i.share2024Pct}% of 2024 world`
          : `${i.yoy2025Pct}% YoY 2025`,
    }));
  }, [industryLens]);

  const scatterData = useMemo(
    () =>
      SHARE_GROWTH_SCATTER.map((p) => ({
        ...p,
        x: p.sharePct,
        y: p.yoyPct,
        z: Math.max(40, Math.sqrt(p.units) / 8),
      })),
    [],
  );

  const pathLineData = useMemo(
    () =>
      TOP_K_PATH.map((row) => ({
        vintage: row.vintage,
        value:
          pathSeries === "hhi"
            ? row.hhi
            : pathSeries === "asia"
              ? row.asia
              : pathSeries === "top5"
                ? row.top5
                : pathSeries === "top3"
                  ? row.top3
                  : row.top1,
      })),
    [pathSeries],
  );

  return (
    <div
      className="space-y-6"
      data-viz="industrial-robotics-concentration-2026q3"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-5 text-white shadow-sm sm:px-6">
        <p className="text-xs font-semibold uppercase tracking-wider text-amber-300/90">
          Industrial robotics ??? Q3 2026 concentration
        </p>
        <p className="mt-2 max-w-3xl text-sm leading-relaxed text-slate-200 sm:text-base">
          On 2025 prelim installs, Top-1 China holds{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.top1SharePct, 1)}
          </span>{" "}
          ({fmtPp(HEADLINE.top1DeltaPp)} vs 2024 WR). Top-3 reaches{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.top3SharePct, 1)}
          </span>
          ; Top-5{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.top5SharePct, 1)}
          </span>
          . Asia&apos;s regional share tightened from{" "}
          {HEADLINE.asiaShare2024Pct}% ??? {HEADLINE.asiaShare2025Pct}%.
        </p>
        <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
          {TOP_K_LADDER.map((row) => (
            <div
              key={row.k}
              className="rounded-lg border border-white/10 bg-white/5 px-3 py-2"
            >
              <p className="text-[11px] uppercase tracking-wide text-slate-400">
                {row.label} 2025
              </p>
              <p className="text-xl font-bold tabular-nums text-white">
                {fmtPct(row.share2025Pct, 1)}
              </p>
              <p className="text-[11px] text-amber-300/90">
                {fmtPp(row.deltaPp)} ?? {row.note}
              </p>
            </div>
          ))}
          <div className="rounded-lg border border-white/10 bg-white/5 px-3 py-2">
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              Market HHI
            </p>
            <p className="text-xl font-bold tabular-nums text-white">
              {HEADLINE.marketHhi2025.toLocaleString()}
            </p>
            <p className="text-[11px] text-amber-300/90">
              +{HEADLINE.hhiDelta} vs 2024
            </p>
          </div>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-4">
        <ToggleGroup
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "ladder", label: "Concentration ladder" },
            { id: "path", label: "2024???2025 path" },
            { id: "regions", label: "Regions" },
            { id: "industry", label: "Industry + suppliers" },
          ]}
        />
        {view === "ladder" && (
          <>
            <ToggleGroup
              label="Metric"
              value={ladderMetric}
              onChange={setLadderMetric}
              options={[
                { id: "share2025Pct", label: "Share %" },
                { id: "units2025", label: "Units" },
                { id: "cumulative2025Pct", label: "Cumulative %" },
              ]}
            />
            <label className="flex items-center gap-2 text-sm text-slate-600">
              <input
                type="checkbox"
                checked={showEqualLine}
                onChange={(e) => setShowEqualLine(e.target.checked)}
                className="rounded border-slate-300"
              />
              Equal-split line
            </label>
          </>
        )}
        {view === "path" && (
          <ToggleGroup
            label="Series"
            value={pathSeries}
            onChange={setPathSeries}
            options={[
              { id: "top1", label: "Top-1" },
              { id: "top3", label: "Top-3" },
              { id: "top5", label: "Top-5" },
              { id: "asia", label: "Asia %" },
              { id: "hhi", label: "HHI" },
            ]}
          />
        )}
        {view === "regions" && (
          <ToggleGroup
            label="Vintage"
            value={regionVintage}
            onChange={setRegionVintage}
            options={[
              { id: "2025", label: "2025 prelim" },
              { id: "2024", label: "2024 WR" },
            ]}
          />
        )}
        {view === "industry" && (
          <ToggleGroup
            label="Lens"
            value={industryLens}
            onChange={setIndustryLens}
            options={[
              { id: "share", label: "2024 share" },
              { id: "yoy", label: "2025 YoY" },
            ]}
          />
        )}
      </div>

      {view === "ladder" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Cumulative share vs equal split"
            subtitle="Lorenz-style curve on 2025 prelim installs ??? Top-1 alone clears 61%"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={CONCENTRATION_CURVE}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="rank" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      String(name),
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.market
                        ? `Rank ${payload[0].payload.rank}: ${payload[0].payload.market}`
                        : ""
                    }
                  />
                  <Area
                    type="monotone"
                    dataKey="cumulativeSharePct"
                    name="Cumulative 2025"
                    fill={ROSE}
                    fillOpacity={0.15}
                    stroke={ROSE}
                    strokeWidth={2}
                  />
                  {showEqualLine && (
                    <Line
                      type="monotone"
                      dataKey="equalSharePct"
                      name="Equal split"
                      stroke={SLATE}
                      strokeDasharray="4 4"
                      dot={false}
                      strokeWidth={1.5}
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Ranked 2025 market shares"
            subtitle={
              ladderMetric === "share2025Pct"
                ? "% of 2025 prelim world installations"
                : ladderMetric === "units2025"
                  ? "2025 prelim installations (units)"
                  : "Cumulative share through this rank"
            }
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={ladderBars} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) =>
                      ladderMetric === "units2025" ? fmtUnits(v) : `${v}%`
                    }
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={64}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [
                      ladderMetric === "units2025"
                        ? fmtUnits(Number(v))
