                type="checkbox"
                checked={showEqualLine}
                onChange={(e) => setShowEqualLine(e.target.checked)}
                className="rounded border-slate-300"
              />
              Equal-split line
            </label>
          </>
        )}
        {view === "path" && (
          <ToggleGroup
            label="Series"
            value={pathSeries}
            onChange={setPathSeries}
            options={[
              { id: "top1", label: "Top-1" },
              { id: "top3", label: "Top-3" },
              { id: "top5", label: "Top-5" },
              { id: "asia", label: "Asia %" },
              { id: "hhi", label: "HHI" },
            ]}
          />
        )}
        {view === "regions" && (
          <ToggleGroup
            label="Vintage"
            value={regionVintage}
            onChange={setRegionVintage}
            options={[
              { id: "2025", label: "2025 prelim" },
              { id: "2024", label: "2024 WR" },
            ]}
          />
        )}
        {view === "industry" && (
          <ToggleGroup
            label="Lens"
            value={industryLens}
            onChange={setIndustryLens}
            options={[
              { id: "share", label: "2024 share" },
              { id: "yoy", label: "2025 YoY" },
            ]}
          />
        )}
      </div>

      {view === "ladder" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Cumulative share vs equal split"
            subtitle="Lorenz-style curve on 2025 prelim installs ??? Top-1 alone clears 61%"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={CONCENTRATION_CURVE}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="rank" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      String(name),
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.market
                        ? `Rank ${payload[0].payload.rank}: ${payload[0].payload.market}`
                        : ""
                    }
                  />
                  <Area
                    type="monotone"
                    dataKey="cumulativeSharePct"
                    name="Cumulative 2025"
                    fill={ROSE}
                    fillOpacity={0.15}
                    stroke={ROSE}
                    strokeWidth={2}
                  />
                  {showEqualLine && (
                    <Line
                      type="monotone"
                      dataKey="equalSharePct"
                      name="Equal split"
                      stroke={SLATE}
                      strokeDasharray="4 4"
                      dot={false}
                      strokeWidth={1.5}
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Ranked 2025 market shares"
            subtitle={
              ladderMetric === "share2025Pct"
                ? "% of 2025 prelim world installations"
                : ladderMetric === "units2025"
                  ? "2025 prelim installations (units)"
                  : "Cumulative share through this rank"
            }
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={ladderBars} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) =>
                      ladderMetric === "units2025" ? fmtUnits(v) : `${v}%`
                    }
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={64}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [
                      ladderMetric === "units2025"
                        ? fmtUnits(Number(v))
                        : fmtPct(Number(v), 1),
                      ladderMetric === "share2025Pct"
                        ? "Share"
                        : ladderMetric === "units2025"
                          ? "Units"
                          : "Cumulative",
                    ]}
                  />
                  <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                    {ladderBars.map((m) => (
                      <Cell key={m.market} fill={m.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "path" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Concentration path: 2024 WR ??? 2025 prelim"
            subtitle={
              pathSeries === "hhi"
                ? "Approximate market HHI (0???10,000)"
                : "Share of world installations"
            }
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={pathLineData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="vintage" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) =>
                      pathSeries === "hhi" ? String(v) : `${v}%`
                    }
                    domain={
                      pathSeries === "hhi"
                        ? [2800, 4200]
                        : pathSeries === "asia"
                          ? [70, 82]
                          : [50, 90]
                    }
                  />
                  <Tooltip
                    formatter={(v) => [
                      pathSeries === "hhi"
                        ? Number(v).toLocaleString()
                        : fmtPct(Number(v), 1),
                      pathSeries.toUpperCase(),
                    ]}
                  />
                  <Line
                    type="monotone"
                    dataKey="value"
                    stroke={ROSE}
                    strokeWidth={3}
                    dot={{ r: 5, fill: ROSE }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Share delta bridge (pp of world)"
            subtitle="Who gained or lost percentage points of global installs"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={SHARE_DELTA_BRIDGE}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="market" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}pp`}
                  />
                  <Tooltip
                    formatter={(v) => [fmtPp(Number(v)), "?? share"]}
                  />
                  <Bar dataKey="deltaPp" radius={[4, 4, 0, 0]}>
                    {SHARE_DELTA_BRIDGE.map((d) => (
                      <Cell
                        key={d.market}
                        fill={d.deltaPp >= 0 ? ROSE : SKY}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Top-k ladder comparison"
            subtitle="Every rung of the concentration ladder tightened"
          >
            <div className="h-64 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={TOP_K_LADDER}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[50, 90]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      fmtPct(Number(v), 1),
                      String(name),
                    ]}
                  />
                  <Bar
                    dataKey="share2024Pct"
                    name="2024 WR"
                    fill={SLATE}
                    radius={[4, 4, 0, 0]}
                  />
                  <Bar
                    dataKey="share2025Pct"
                    name="2025 prelim"
                    fill={AMBER}
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="What the path says"
            subtitle="Re-acceleration did not diversify demand ??? it concentrated it"
          >
            <ul className="space-y-3 text-sm leading-relaxed text-slate-700">
              <li>
                <span className="font-semibold text-slate-900">Top-1:</span>{" "}
                China {fmtPct(HEADLINE.top1Share2024Pct, 1)} ???{" "}
                {fmtPct(HEADLINE.top1SharePct, 1)} ({fmtPp(HEADLINE.top1DeltaPp)}
                ) on an IFR ~10?? US estimate.
              </li>
              <li>
                <span className="font-semibold text-slate-900">Top-3 / Top-5:</span>{" "}
                {fmtPct(HEADLINE.top3Share2024Pct, 1)} ???{" "}
                {fmtPct(HEADLINE.top3SharePct, 1)} and{" "}
                {fmtPct(HEADLINE.top5Share2024Pct, 1)} ???{" "}
                {fmtPct(HEADLINE.top5SharePct, 1)}.
              </li>
              <li>
                <span className="font-semibold text-slate-900">HHI:</span>{" "}
                {HEADLINE.marketHhi2024.toLocaleString()} ???{" "}
                {HEADLINE.marketHhi2025.toLocaleString()} (+{HEADLINE.hhiDelta}
                ). Equal 10-market HHI would be ~{HEADLINE.equal10Hhi}.
              </li>
              <li className="text-slate-500">
                US share slipped slightly (6.3% ??? 6.1%) even as units rose +11%
                ??? growth without share gain when the world grows faster.
              </li>
            </ul>
          </ChartCard>
        </div>
      )}

      {view === "regions" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title={`${regionVintage === "2025" ? "2025 prelim" : "2024 WR"} regional install share`}
            subtitle={
              regionVintage === "2025"
                ? "Asia 79% ??? one continent owns four-fifths of the flow"
                : "Asia 74% ??? already the gravity well before re-acceleration"
            }
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={regionDonut}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={95}
                    paddingAngle={2}
                    label={({ name, value }) => `${name} ${value}%`}
                  >
                    {regionDonut.map((d) => (
                      <Cell key={d.name} fill={d.fill} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v) => [`${v}%`, "Share"]} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Region units: 2024 ??? 2025"
            subtitle="Asia added ~89k units; Europe contracted; Americas rebounded"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={REGION_SHARES}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => fmtUnits(v)}
                  />
                  <Tooltip
                    formatter={(v) => [fmtUnits(Number(v)), "Units"]}
                  />
                  <Bar
                    dataKey="units2024"
                    name="2024 WR"
                    fill={SLATE}
                    radius={[4, 4, 0, 0]}
                  />
                  <Bar
                    dataKey="units2025"
                    name="2025 prelim"
                    fill={AMBER}
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Share ?? growth scatter"
            subtitle="Who is large and still adding? Bubble ??? 2025 units"
          >
            <div className="h-64 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 8, right: 12, bottom: 8, left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Share %"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    label={{
                      value: "2025 install share %",
                      position: "insideBottom",
                      offset: -2,
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="YoY %"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <ZAxis type="number" dataKey="z" range={[40, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      String(name),
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.market ?? ""
                    }
                  />
                  <Scatter data={scatterData} name="Markets">
                    {scatterData.map((p) => (
                      <Cell key={p.market} fill={p.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Regional concentration read"
            subtitle="Geography tightened further as the world re-accelerated"
          >
            <ul className="space-y-3 text-sm leading-relaxed text-slate-700">
              <li>
                Asia&apos;s share rose {HEADLINE.asiaShare2024Pct}???
                {HEADLINE.asiaShare2025Pct}% while Europe compressed{" "}
                {HEADLINE.europeShare2024Pct}???{HEADLINE.europeShare2025Pct}%.
              </li>
              <li>
                Americas held {HEADLINE.americasShare2025Pct}% of world installs
                even as US units flipped to +11% ??? share-stable, not share-gaining.
              </li>
              <li>
                China sits alone in the high-share / high-YoY quadrant on the
                scatter; India is small-share / high-growth; Germany is mid-share
                / negative.
              </li>
            </ul>
          </ChartCard>
        </div>
      )}

      {view === "industry" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title={
              industryLens === "share"
                ? "Customer industry share of world installs (2024)"
                : "Customer industry YoY (2025 prelim)"
            }
            subtitle={
              industryLens === "share"
                ? "Top-2 (electronics + auto) ??? 47% ??? flatter than geography"
                : "Electronics led re-acceleration at +25%"
            }
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={industryBars}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, _n, item) => [
                      `${v}%`,
                      item?.payload?.label ?? "Value",
                    ]}
                  />
                  <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                    {industryBars.map((i) => (
                      <Cell key={i.industry} fill={i.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="China domestic vs foreign supplier share"
            subtitle="First domestic majority in 2024 ??? still the supplier-side concentration story"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={CHINA_SUPPLIER_SERIES}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip formatter={(v, name) => [`${v}%`, String(name)]} />
                  <Area
                    type="monotone"
                    dataKey="domesticPct"
                    name="Domestic"
                    stackId="1"
                    stroke={ROSE}
                    fill={ROSE}
                    fillOpacity={0.7}
                  />
                  <Area
                    type="monotone"
                    dataKey="foreignPct"
                    name="Foreign"
                    stackId="1"
                    stroke={SKY}
                    fill={SKY}
                    fillOpacity={0.55}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Industry vs geography"
            subtitle="Customer mix is less concentrated than country mix ??? but China still owns the lead verticals"
          >
            <div className="space-y-4 text-sm leading-relaxed text-slate-700">
              <p>
                Electronics and automotive together are under half of world
                installs ??? a flatter industry distribution than the geography
                ladder, where Top-1 alone is{" "}
                {fmtPct(HEADLINE.top1SharePct, 1)} on 2025 prelims.
              </p>
              <p>
                Inside those lead verticals, China still dominates: ~64% of
                global electronics robot installs and ~45% of automotive (2024
                disclosed bases). Re-acceleration at +25% electronics YoY
                reinforces, rather than dilutes, that China-centric demand.
              </p>
              <div className="grid grid-cols-2 gap-2">
                <div className="rounded-lg border border-slate-100 bg-slate-50 px-3 py-2">
                  <p className="text-[11px] uppercase text-slate-500">
                    CN domestic 2024
                  </p>
                  <p className="text-lg font-bold text-slate-900">
                    {fmtPct(HEADLINE.chinaDomesticSupplierPct)}
                  </p>
                </div>
                <div className="rounded-lg border border-slate-100 bg-slate-50 px-3 py-2">
                  <p className="text-[11px] uppercase text-slate-500">
                    Electronics YoY
                  </p>
                  <p className="text-lg font-bold text-slate-900">
                    +{HEADLINE.electronicsYoyPct}%
                  </p>
                </div>
              </div>
            </div>
          </ChartCard>

          <ChartCard
            title="Color key"
            subtitle="Consistent fills across panels"
          >
            <div className="flex flex-wrap gap-2 text-xs">
              <span
                className="rounded-md px-2.5 py-1 font-medium text-white"
                style={{ backgroundColor: ROSE }}
              >
                China / auto / domestic
              </span>
              <span
                className="rounded-md px-2.5 py-1 font-medium text-white"
                style={{ backgroundColor: AMBER }}
              >
                Asia / Japan / metal
              </span>
              <span
                className="rounded-md px-2.5 py-1 font-medium text-white"
                style={{ backgroundColor: SKY }}
              >
                US / electronics / foreign
              </span>
              <span
                className="rounded-md px-2.5 py-1 font-medium text-white"
                style={{ backgroundColor: VIOLET }}
              >
                Korea / Europe / plastic
              </span>
              <span
                className="rounded-md px-2.5 py-1 font-medium text-white"
                style={{ backgroundColor: TEAL }}
              >
                Germany / food
              </span>
            </div>
            <p className="mt-4 text-xs text-slate-500">{SOURCE_NOTE}</p>
          </ChartCard>
        </div>
      )}

      {view !== "industry" && (
        <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      )}
    </div>
  );
}

