"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CHINA_SUPPLIER_SERIES,
  CONCENTRATION_CURVE,
  HEADLINE,
  INDUSTRY_SHARES,
  MARKET_SHARES,
  REGION_SHARES,
  SHARE_DELTA_BRIDGE,
  SHARE_GROWTH_SCATTER,
  SOURCE_NOTE,
  TOP_K_LADDER,
  TOP_K_PATH,
  fmtPct,
  fmtPp,
  fmtUnits,
} from "@/data/industrial-robotics-concentration-2026q3-data";

// viz-types: Lorenz area+line, ranked share bars, path multi-line, share-delta bars, region donut, supplier stacked area, industry bars, share??growth scatter | layout: default

type ViewId = "ladder" | "path" | "regions" | "industry";
type LadderMetric = "share2025Pct" | "units2025" | "cumulative2025Pct";
type PathSeries = "top1" | "top3" | "top5" | "asia" | "hhi";

const ROSE = "#f43f5e";
const AMBER = "#f59e0b";
const SKY = "#0ea5e9";
const VIOLET = "#8b5cf6";
const TEAL = "#14b8a6";
const SLATE = "#64748b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function IndustrialRoboticsConcentration2026q3Dashboard() {
  const [view, setView] = useState<ViewId>("ladder");
  const [ladderMetric, setLadderMetric] = useState<LadderMetric>("share2025Pct");
  const [showEqualLine, setShowEqualLine] = useState(true);
  const [pathSeries, setPathSeries] = useState<PathSeries>("top1");
  const [industryLens, setIndustryLens] = useState<"share" | "yoy">("share");
  const [regionVintage, setRegionVintage] = useState<"2024" | "2025">("2025");

  const ladderBars = useMemo(() => {
    return [...MARKET_SHARES]
      .map((m) => ({
        ...m,
        value:
          ladderMetric === "share2025Pct"
            ? m.share2025Pct
            : ladderMetric === "units2025"
              ? m.units2025
              : m.cumulative2025Pct,
      }))
      .sort((a, b) => b.value - a.value);
  }, [ladderMetric]);

  const regionDonut = useMemo(
    () =>
      REGION_SHARES.map((r) => ({
        name: r.short,
        value: regionVintage === "2025" ? r.share2025Pct : r.share2024Pct,
        fill: r.fill,
      })),
    [regionVintage],
  );

  const industryBars = useMemo(() => {
    return INDUSTRY_SHARES.map((i) => ({
      ...i,
      value: industryLens === "share" ? i.share2024Pct : i.yoy2025Pct,
      label:
        industryLens === "share"
          ? `${i.share2024Pct}% of 2024 world`
          : `${i.yoy2025Pct}% YoY 2025`,
    }));
  }, [industryLens]);

  const scatterData = useMemo(
    () =>
      SHARE_GROWTH_SCATTER.map((p) => ({
        ...p,
        x: p.sharePct,
        y: p.yoyPct,
        z: Math.max(40, Math.sqrt(p.units) / 8),
      })),
    [],
  );

  const pathLineData = useMemo(
    () =>
      TOP_K_PATH.map((row) => ({
        vintage: row.vintage,
        value:
          pathSeries === "hhi"
            ? row.hhi
            : pathSeries === "asia"
              ? row.asia
              : pathSeries === "top5"
                ? row.top5
                : pathSeries === "top3"
                  ? row.top3
                  : row.top1,
      })),
    [pathSeries],
  );

  return (
    <div
      className="space-y-6"
      data-viz="industrial-robotics-concentration-2026q3"
    >
