          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.top3SharePct, 1)}
          </span>
          ; Top-5{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.top5SharePct, 1)}
          </span>
          . Asia&apos;s regional share tightened from{" "}
          {HEADLINE.asiaShare2024Pct}% ??? {HEADLINE.asiaShare2025Pct}%.
