                    type="category"
                    dataKey="short"
                    width={64}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [
                      ladderMetric === "units2025"
                        ? fmtUnits(Number(v))
                        : fmtPct(Number(v), 1),
                      ladderMetric === "share2025Pct"
                        ? "Share"
                        : ladderMetric === "units2025"
                          ? "Units"
                          : "Cumulative",
                    ]}
                  />
                  <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                    {ladderBars.map((m) => (
                      <Cell key={m.market} fill={m.fill} />
