                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "path" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Concentration path: 2024 WR ??? 2025 prelim"
            subtitle={
              pathSeries === "hhi"
                ? "Approximate market HHI (0???10,000)"
                : "Share of world installations"
            }
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={pathLineData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="vintage" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) =>
                      pathSeries === "hhi" ? String(v) : `${v}%`
                    }
                    domain={
                      pathSeries === "hhi"
                        ? [2800, 4200]
                        : pathSeries === "asia"
                          ? [70, 82]
