                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="China domestic vs foreign supplier share"
            subtitle="First domestic majority in 2024 ??? still the supplier-side concentration story"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={CHINA_SUPPLIER_SERIES}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip formatter={(v, name) => [`${v}%`, String(name)]} />
                  <Area
                    type="monotone"
                    dataKey="domesticPct"
                    name="Domestic"
                    stackId="1"
                    stroke={ROSE}
                    fill={ROSE}
                    fillOpacity={0.7}
                  />
                  <Area
                    type="monotone"
                    dataKey="foreignPct"
                    name="Foreign"
                    stackId="1"
                    stroke={SKY}
                    fill={SKY}
                    fillOpacity={0.55}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Industry vs geography"
            subtitle="Customer mix is less concentrated than country mix ??? but China still owns the lead verticals"
          >
            <div className="space-y-4 text-sm leading-relaxed text-slate-700">
              <p>
                Electronics and automotive together are under half of world
                installs ??? a flatter industry distribution than the geography
                ladder, where Top-1 alone is{" "}
                {fmtPct(HEADLINE.top1SharePct, 1)} on 2025 prelims.
              </p>
              <p>
                Inside those lead verticals, China still dominates: ~64% of
                global electronics robot installs and ~45% of automotive (2024
                disclosed bases). Re-acceleration at +25% electronics YoY
                reinforces, rather than dilutes, that China-centric demand.
              </p>
              <div className="grid grid-cols-2 gap-2">
                <div className="rounded-lg border border-slate-100 bg-slate-50 px-3 py-2">
                  <p className="text-[11px] uppercase text-slate-500">
                    CN domestic 2024
                  </p>
                  <p className="text-lg font-bold text-slate-900">
                    {fmtPct(HEADLINE.chinaDomesticSupplierPct)}
                  </p>
                </div>
                <div className="rounded-lg border border-slate-100 bg-slate-50 px-3 py-2">
                  <p className="text-[11px] uppercase text-slate-500">
                    Electronics YoY
                  </p>
                  <p className="text-lg font-bold text-slate-900">
                    +{HEADLINE.electronicsYoyPct}%
                  </p>
                </div>
              </div>
            </div>
          </ChartCard>

          <ChartCard
            title="Color key"
            subtitle="Consistent fills across panels"
          >
            <div className="flex flex-wrap gap-2 text-xs">
              <span
                className="rounded-md px-2.5 py-1 font-medium text-white"
                style={{ backgroundColor: ROSE }}
              >
                China / auto / domestic
              </span>
              <span
                className="rounded-md px-2.5 py-1 font-medium text-white"
                style={{ backgroundColor: AMBER }}
              >
                Asia / Japan / metal
              </span>
              <span
                className="rounded-md px-2.5 py-1 font-medium text-white"
                style={{ backgroundColor: SKY }}
              >
                US / electronics / foreign
              </span>
              <span
                className="rounded-md px-2.5 py-1 font-medium text-white"
                style={{ backgroundColor: VIOLET }}
              >
                Korea / Europe / plastic
              </span>
              <span
                className="rounded-md px-2.5 py-1 font-medium text-white"
                style={{ backgroundColor: TEAL }}
              >
                Germany / food
              </span>
            </div>
            <p className="mt-4 text-xs text-slate-500">{SOURCE_NOTE}</p>
          </ChartCard>
        </div>
      )}

      {view !== "industry" && (
        <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      )}
    </div>
  );
}

